      'la-belle', '03', 'La Belle', 'La Belle — Case Study — Captionz',
      'From advertising to experience — building La Belle into a name people trust for skin, hair and slimming care.', 'Skin · Hair · Slimming', NULL, 'branding',
      'Case Study', 0, '/assets/logo-labelle.png', '#077D7A',
      'From advertising to experience — the brand Captionz calls its biggest example.', 1, '/assets/logo-labelle.png', '{"src":"https://pub-97c17fb137b447f6a52871a6328a8f1a.r2.dev/works/966e27e59b_AHkbwyIujWVCumyxrUmmEKU7zswzXmDTbTFJk14g.jpg","alt":"La Belle — The La Belle Evolution: From Advertising to Experience, case study cover."}',
      '{"text":"Captionz always said, they made names into brands — and La Belle is the biggest example in his book.","attr":"Deepak Mittal — Founder, La Belle"}', '["Skin, hair and slimming care — a category built on trust. The work carried La Belle from advertising into a fuller brand experience, giving a name that clients had already come to trust a visual identity to match."]', NULL,
      '["From advertising to experience — building La Belle into a name people trust for skin, hair and slimming care."]', '[]', '{"slug":"minitech","href":"/work/minitech","label":"Next Case Study","name":"Minitech"}',
      '{"href":"/case-study","label":"Back to Case Study"}'
    );
